function loadXML(xml)
{
  if (window.DOMParser)
    return new DOMParser().parseFromString(xml,"text/xml");
  else // Internet Explorer
  {
    xmlDoc=new ActiveXObject("Microsoft.XMLDOM");
    xmlDoc.async=false;
    xmlDoc.loadXML(xml);
    return xmlDoc;
  }
}

