import { Format } from "../core/elements/format"
import { Series } from "../series"
import { Animation, Annotation } from "../tools/index"

/**
 *@constructor
 *@memberOf Tee
 *@class Parameters to draw a circular gauge meter.
 *@property {Number} [min=0] The minimum gauge range value.
 *@property {Number} [max=100] The maxnimum gauge range value.
 *@property {Number} [step=0] The increment between gauge range labels.
 *@property {Number} [value=0] The position of gauge hand inside the min max range.
 *@property {Number} [angle=280] Amount in degrees of the circular gauge size.
 *@property {Number} [rotation=0] Gauge rotation in degrees.
 *@property {Boolean} [rotateText=false] Gauge labels are rotated or not according to label angle position.
 *@property {String} [shape="circle"] Gauge style ("circle", "rectangle", "segment").
 *@property {Boolean} [drag.enabled=true] Allows mouse/touch dragging the Gauge hand to change current value.
 *@property {Tee.Format} bevel Formatting properties to outmost external gauge bevel.
 *@property {Tee.Format} center Formatting properties for center gauge symbol.
 */
export class NumericGauge extends Series {
	useAxes = false

	// Range and value:
	min = 0
	max = 100
	step = 0
	value = 0

	// Rotation options:
	angle = 280 // degree
	rotation = 0 // degree
	rotateText = false
	shape = "rectangle" // rectangle, segment

	drag = { enabled: true }
	markers = []
	oldValue = undefined
	newValue = undefined
	tick0 = undefined
	tick1 = undefined
	tickMin = undefined
	tickText = undefined
	initRot = undefined
	endRot = undefined
	cx = undefined
	cy = undefined
	cex = undefined
	cey = undefined
	p = { x: 0, y: 0 }

	constructor(o, o2) {
		super(o, o2)

		// no axis
		this.legend.visible = false

		this.bevel = new Format(this.chart)
		this.bevel.gradient.visible = true
		this.bevel.gradient.colors = ["white"]
		this.bevel.shadow.visible = false
		this.bevel.visible = false
		this.bevel.stroke.fill = ""

		this.center = new Format(this.chart)
		this.center.stroke.fill = ""
		this.center.gradient.visible = true
		this.center.size = 10
		this.center.visible = false
		this.center.shadow.visible = true
		this.center.gradient.offset = { x: 2, y: -2 }
		this.center.location = { x: 0, y: 0 } // %

		this.center.top = new Format(this.chart)
		this.center.top.size = 40 // %
		this.center.top.visible = true
		this.center.top.stroke.fill = ""
		this.center.top.gradient.colors = ["silver", "white"]
		this.center.top.gradient.visible = true
		this.center.top.gradient.direction = "topbottom"

		this.ticks = new Format(this.chart)
		this.ticks.length = 6 // %
		this.ticks.stroke.fill = "silver"
		this.ticks.visible = true
		this.ticks.outside = true
		this.ticks.triangle = false
		this.ticks.fill = "white"

		this.ticksBack = new Format(this.chart)
		this.ticksBack.stroke.fill = ""
		this.ticksBack.fill = "black"
		this.ticksBack.gradient.visible = true
		this.ticksBack.gradient.colors = ["red", "yellow", "green"]
		this.ticksBack.gradient.direction = "rightleft"
		this.ticksBack.visible = false
		this.ticksBack.radius = 0

		this.minor = new Format(this.chart)
		this.minor.stroke.fill = "silver"
		this.minor.visible = true
		this.minor.count = 4
		this.minor.shape = "" // ellipse

		this.minorBack = new Format(this.chart)
		this.minorBack.stroke.fill = ""
		this.minorBack.visible = false
		this.minorBack.fill = "white"
		this.minorBack.gradient.visible = false
		this.minorBack.gradient.direction = "leftright"
		this.minorBack.gradient.colors = ["green", "yellow", "red"]
		this.minorBack.radius = 0

		// shape background
		this.back = new Format(this.chart)
		this.back.fill = "black"
		this.back.visible = true
		this.back.gradient.visible = false
		this.back.gradient.colors = ["rgba(255,126,95,0.8)", "rgba(254,180,123,0.8)"]
		this.back.stroke.fill = ""

		this.pointer = new Format(this.chart)
		this.pointer.size = 3
		this.pointer.fill = "black"
		this.pointer.stroke.fill = ""
		this.pointer.visible = false

		this.marks.format.fill = "black"
		this.marks.format.font.fill = "black"
		this.marks.format.gradient.visible = true
		this.marks.format.gradient.colors = ["rgba(255,126,95,0.6)", "rgba(254,180,123,0.6)"]
		this.marks.format.shadow.visible = true
		this.marks.format.shadow.blur = 8
		this.marks.format.shadow.color = "black"

		this.format.visible = true
		this.format.gradient.visible = true
		this.format.gradient.colors = ["white"]
		this.format.shadow.visible = true
		this.format.font.style = "12px Verdana"
		this.format.font.fill = "black"
		this.format.font.visible = true
		this.format.size = 2 // %
		this.format.round = { x: 6, y: 6 }

		this.format.padding = 0 // %

		this.units = new Annotation(this.chart)
		this.units.transparent = true
		this.units.format.font.fill = "black"
		this.units.location = { x: 0, y: 24 } // %

		this.bounds = this.getRect()

		// markers (Text, Value and Units)
		this.valueMarker = this.addValueMarker()
		this.textMarker = this.addTextMarker()
		this.unitsMarker = this.addUnitsMarker()

		this.hover.enabled = true

		this.animate = new Animation(this.chart, fAnimation => {
			this.value = this.oldValue + fAnimation * (this.newValue - this.oldValue)
			this.chart.draw()
		})

		this.animate.duration = 100
		this.animate.onstop = () => {
			this.value = this.newValue

			if (this.onchange) this.onchange(this)

			this.chart.draw()
		}
	}

	addValueMarker() {
		const marker = new Format(this.chart)

		marker.fill = "white"
		marker.font.fill = "black"
		marker.font.style = "82px Arial"
		marker.stroke.color = "white"
		marker.text = "0"

		marker.location = { x: 38, y: 6 } // %
		marker.position = { x: 30, y: 40 } // %
		marker.width = 60 // %
		marker.height = 88 // %

		marker.shape = "rectangle"

		marker.visible = true

		this.markers.push(marker)
		return marker
	}

	addTextMarker() {
		const marker = new Format(this.chart)

		marker.fill = "white"
		marker.font.fill = "black"
		marker.font.style = "40px Arial"
		marker.font.textAlign = "left"
		marker.stroke.color = "white"
		marker.text = "FREQ"

		marker.location = { x: 1, y: 5 } // %
		marker.position = { x: 37, y: 25 } // %
		marker.width = 20 // %
		marker.height = 20 // %

		marker.shape = "rectangle"

		marker.visible = true

		this.markers.push(marker)
		return marker
	}

	addUnitsMarker() {
		const marker = new Format(this.Chart)
		marker.fill = "white"
		marker.font.fill = "black"
		marker.font.style = "40px Arial"
		marker.font.textAlign = "left"
		marker.stroke.color = "white"
		marker.text = "Mhz"

		marker.location = { x: 1, y: 55 } // %
		marker.position = { x: 37, y: 32 } // %
		marker.width = 20 // %
		marker.height = 41 // %

		marker.shape = "rectangle"

		marker.visible = true

		this.markers.push(marker)
		return marker
	}

	calcBounds() {
		return this.bounds.custom ? this.bounds : this.cellRect(this.bounds, true)
	}

	drawMarker(marker, bounds, ctx) {
		if (marker.visible) {
			// marker shape
			const shapeWidth = (bounds.width * marker.width) / 100
			const shapeHeight = (bounds.height * marker.height) / 100
			const shapeLocation = {
				x: (bounds.width * marker.location.x) / 100,
				y: (bounds.height * marker.location.y) / 100
			}
			ctx.fillStyle = marker.fill
			ctx.fillRect(shapeLocation.x, shapeLocation.y, shapeWidth, shapeHeight)
			ctx.font = marker.font.style
			ctx.fillStyle = marker.font.fill

			// marker text
			const lblX = shapeLocation.x + (shapeWidth * marker.position.x) / 100
			const lblY = shapeLocation.y + (shapeHeight * marker.position.y) / 100
			ctx.fillText(marker.text, lblX, lblY)
			ctx.save()
		}
	}

	draw() {
		const ctx = this.chart.ctx

		const bounds = this.calcBounds()

		if (this.back.visible) {
			ctx.fillStyle = this.back.fill
			ctx.fillRect(0, 0, bounds.width, bounds.height)
			ctx.save()
		}

		this.markers.forEach(marker => {
			this.drawMarker(marker, bounds, ctx)
		})
	}

	limitValue(v) {
		return Math.min(this.max, Math.max(this.min, v))
	}

	setValue(v) {
		v = this.limitValue(v)

		const res = this.value !== v

		if (res) {
			if (this.animate.active && this.animate.duration > 0) {
				this.oldValue = this.value
				this.newValue = v
				this.animate.animate(this.chart)
			} else {
				this.value = v

				if (this.onchange) this.onchange(this)
			}
		}
		this.valueMarker.text = v.toFixed()

		return res
	}

	onclick() {}

	clicked() {
		this.dragging = false
		return -1
	}

	inValue(p, r) {
		if (!r.contains(p)) return false

		const dx = p.x - this.cex,
			dy = p.y - this.cey,
			d = Math.sqrt(dx * dx + dy * dy)

		let ang = Math.atan2(dy, dx) - Math.PI * 0.5
		while (ang < 0) ang += 6.283

		let rIni, rEnd, val

		if (this.initRot > this.endRot) {
			rIni = this.endRot
			rEnd = this.initRot
			val = ang >= rEnd || ang <= rIni
		} else {
			rEnd = this.endRot
			rIni = this.initRot
			val = ang >= rIni && ang <= rEnd
		}

		if (val) {
			let res

			if (this.initRot > this.endRot)
				if (ang > rEnd) res = (ang - rEnd) / (6.283 - rEnd + rIni)
				else res = (6.283 - rEnd + ang) / (6.283 - rEnd + rIni)
			else res = (ang - rIni) / (rEnd - rIni)

			let v = this.min + (this.max - this.min) * res

			if (this.inverted) v = this.min + (this.max - this.min) * (1 - res)

			p.value = v

			p.inTicks = d >= Math.min(this.tick0, this.tickText) && d <= this.tick1

			return true
		} else {
			p.inTicks = false
			return false
		}
	}

	changeHover(v) {
		if (this.hover.value !== v) {
			this.hover.value = v
			this.hover.valid = v !== null
			requestAnimationFrame(() => {
				this.chart.draw()
			})
		}
	}

	mousemove(p) {
		const r = this.calcBounds(),
			ok = this.inValue(p, r)
		if (
			this.dragging ||
			(/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) && this.drag.enabled)
		) {
			if (ok && this.setValue(p.value)) this.chart.draw()

			this.chart.newCursor = "pointer"
		} else if (p.inTicks && this.drag.enabled) {
			this.changeHover(p.value)
			this.chart.newCursor = "pointer"
		} else this.changeHover(null)
	}

	mousedown(e) {
		if (this.drag.enabled) {
			const r = this.calcBounds()
			this.chart.calcMouse(e, this.p)

			if (this.inValue(this.p, r)) {
				this.dragging = true

				this.hover.value = null
				this.hover.valid = false

				if (this.setValue(this.p.value)) this.chart.draw()
			} else this.dragging = false

			return this.dragging
		} else return false
	}

	/**
	 * @private
	 */
	setChart(series, chart) {
		super.setChart(series, chart)

		this.chart.panel.margins.bottom = 0
		this.chart.panel.margins.right = 0
		this.chart.panel.margins.top = 0
		this.chart.panel.margins.left = 0

		series.back.setChart(chart)
		series.center.setChart(chart)
		series.center.top.setChart(chart)
		series.ticks.setChart(chart)
		series.ticksBack.setChart(chart)
		series.minor.setChart(chart)
		series.minorBack.setChart(chart)
		series.units.setChart(chart)
		series.pointer.setChart(chart)
		series.bevel.setChart(chart)
	}
}
