export class Table {
	constructor(table, chart) {
		this.header = 0
		this.firstCol = 0
		this.byCols = true
		this.chart = chart
		this._refresh = null

		this.table = table instanceof HTMLTableElement ? table : document.getElementById(table)

		this._onCellClick = event => {
			this.changeCell(event.currentTarget)
		}

		this._onInputChange = event => {
			this.changeValue(event.currentTarget)
		}
	}

	changeCell(cell) {
		if (!(cell instanceof HTMLTableCellElement)) {
			return
		}

		cell.onclick = null

		const input = document.createElement("input")
		input.type = "text"
		input.style.width = `${cell.clientWidth}px`

		input.onchange = this._onInputChange
		input.onkeydown = this.keyDown.bind(this)
		input.onblur = this._onInputChange
		input.value = cell.innerHTML

		input.className = "inline-editor"

		cell.innerHTML = ""
		cell.appendChild(input)

		cell.firstChild.focus()
	}

	keyDown(e) {
		const key = window.event ? window.event.keyCode : e?.which

		if (!key) {
			return true
		}

		const input = e?.currentTarget
		const c = input?.parentNode
		const r = c?.parentNode
		const tbl = r?.parentNode

		if (!c || !r || !tbl) {
			return true
		}

		if (key === 27 || key === 13) {
			this.changeValue(input)
		}

		if (key === 9) {
			if (e?.shiftKey) {
				if (c.cellIndex > this.firstCol) {
					this.changeValue(input)
					this.changeCell(tbl.rows[r.rowIndex].cells[c.cellIndex - 1])
				} else if (r.rowIndex > 1) {
					this.changeValue(input)
					this.changeCell(tbl.rows[r.rowIndex - 1].cells[r.cells.length - 1])
				}
			} else {
				if (c.cellIndex < r.cells.length - 1) {
					this.changeValue(input)
					this.changeCell(tbl.rows[r.rowIndex].cells[c.cellIndex + 1])
				} else if (r.rowIndex < tbl.rows.length - 1) {
					this.changeValue(input)
					this.changeCell(tbl.rows[r.rowIndex + 1].cells[1])
				}
			}
			return false
		} else if (key === 40) {
			if (r.rowIndex < tbl.rows.length - 1) {
				this.changeValue(input)
				this.changeCell(tbl.rows[r.rowIndex + 1].cells[c.cellIndex])
			}
		} else if (key === 38) {
			if (r.rowIndex > this.header) {
				this.changeValue(input)
				this.changeCell(tbl.rows[r.rowIndex - 1].cells[c.cellIndex])
			}
		}

		return true
	}

	changeValue(text) {
		const input = text instanceof HTMLInputElement ? text : null

		if (!input?.onchange) {
			return
		}

		input.onchange = null

		const cell = input.parentNode

		if (cell) {
			cell.innerHTML = input.value
			cell.onclick = this._onCellClick

			if (this._refresh) {
				this._refresh(cell)
			}
		}
	}

	enableRowHighlight(color, panel) {
		if (typeof panel === "string") {
			panel = document.getElementById(panel)
		}

		const ta = this.table

		if (!ta) {
			return
		}

		for (let t = 0; t < ta.rows.length; t++) {
			ta.rows[t].onmouseover = function () {
				this.style.backgroundColor = color

				if (panel) {
					panel.style.visibility = "visible"
				}
			}

			ta.rows[t].onmouseout = function () {
				this.style.backgroundColor = "#FFFFFF"

				if (panel) {
					panel.style.visibility = "hidden"
				}
			}
		}
	}

	refreshCell(cell) {
		const byCols = this.byCols
		let ser
		let row
		let index
		const s = cell.innerHTML
		const chart = this.chart

		if (byCols) {
			row = cell.parentNode.rowIndex
			index = cell.cellIndex
		} else {
			row = cell.cellIndex
			index = cell.parentNode.rowIndex
		}

		if (row === 1) {
			if (index === 1) {
				if (s !== chart.footer.text) {
					chart.footer.text = s
					chart.draw()
				}
			} else {
				ser = chart.series.items[index - 2]
				if (s !== ser.title) {
					ser.title = s
					chart.draw()
				}
			}
		} else {
			row -= 2

			if (index === 1) {
				ser = chart.series.items[0]
				if (s !== ser.data.labels[row]) {
					chart.series.each(s1 => {
						s1.data.labels[row] = s
					})

					chart.draw()
				}
			} else {
				ser = chart.series.items[index - 2]
				const n = parseFloat(s)

				if (n !== ser.data.values[row]) {
					ser.data.values[row] = n
					chart.draw()
				}
			}
		}
	}

	enableEditing(enable, refresh = this.refreshCell.bind(this)) {
		this._refresh = refresh

		const ta = this.table

		if (!ta) {
			return
		}

		const onClick = enable ? this._onCellClick : null

		for (let r = 0; r < ta.rows.length; r++) {
			const cells = ta.rows[r].cells
			for (let c = 0; c < cells.length; c++) {
				cells[c].onclick = onClick
			}
		}
	}

	dohoverCell(cell, active) {
		if (active) {
			cell.style.backgroundColor = "gold"
			cell.style.color = "white"
		} else {
			cell.style.backgroundColor = ""
			cell.style.color = ""
		}
	}

	pointToCell(series, index) {
		const s = series.chart.series.items.indexOf(series) + 2
		const ta = this.table

		if (this.byCols) {
			return ta.rows[index + 2].cells[s]
		}

		return ta.rows[s].cells[index + 2]
	}

	hoverCell(series, index) {
		if (series.over !== -1) {
			this.dohoverCell(this.pointToCell(series, series.over), false)
		}

		if (index !== -1) {
			this.dohoverCell(this.pointToCell(series, index), true)
		}
	}

	orderToIndex(i) {
		let n = -1
		const chart = this.chart

		for (let t = 0; t < chart.series.count(); t++) {
			if (chart.series.items[t].visible) {
				n++
				if (n === i) {
					return t
				}
			}
		}

		return -1
	}

	legendHover(old, index) {
		let bycols = this.byCols
		let pos = 1
		const c = this.chart
		const ta = this.table

		if (c.legend.showValues()) {
			const s = c.series.firstVisible()
			pos = 2 + c.series.items.indexOf(s)
			bycols = !bycols
		}

		if (bycols) {
			if (old !== -1) {
				this.dohoverCell(ta.rows[pos].cells[this.orderToIndex(old) + 2], false)
			}
			if (index !== -1) {
				this.dohoverCell(ta.rows[pos].cells[this.orderToIndex(index) + 2], true)
			}
		} else {
			if (old !== -1) {
				this.dohoverCell(ta.rows[old + 2].cells[pos], false)
			}
			if (index !== -1) {
				this.dohoverCell(ta.rows[index + 2].cells[pos], true)
			}
		}
	}
}
