import { Format } from "./format"
import { Margins } from "./margins"

/**
 * @memberOf Tee.Chart
 * @constructor
 * @public
 * @class Defines the visual properties for chart background
 * @param {Tee.Chart} chart The parent chart this panel object belongs to.
 * @property {Tee.Margins} margins Controls the spacing between background panel to chart contents.
 * @property {Format} format Visual properties to paint the chart panel background.
 * @property {Boolean} transparent Determines if panel background will be filled or not.
 */
export class Panel {
	constructor(chart) {
		this.chart = chart
		this.format = new Format(chart)
		this.format.round.x = 12
		this.format.round.y = 12
		this.format.stroke.size = 3
		this.format.gradient.visible = true
		this.format.gradient.direction = "bottomtop"
		this.format.shadow.visible = true
		this.format.stroke.fill = "#606060"

		this.transparent = !!chart.__webgl

		this.margins = new Margins()
	}

	clear() {
		const b = this.chart.bounds
		this.chart.ctx.clearRect(b.x, b.y, b.width, b.height)
	}

	draw() {
		if (this.transparent || this.chart.__webgl) this.clear()
		else {
			const r = this.chart.chartRect
			const f = this.format
			const sh = f.shadow

			if (sh.visible) {
				r.width -= 0.5 * Math.abs(sh.width) + 2
				r.height -= 0.5 * Math.abs(sh.height) + 2

				if (sh.width < 0) r.x -= sh.width
				if (sh.height < 0) r.y -= sh.height
			}

			let s = 0

			if (f.stroke.fill !== "") {
				s = f.stroke.size
				if (s > 1) {
					s *= 0.5
					r.x += s
					r.y += s
					r.width -= 2 * s
					r.height -= 2 * s
				}
			}

			if (sh.visible || f.round.x > 0 || f.round.y > 0) this.clear()

			f.rectangle(r)

			if (s > 0) {
				r.x += s
				r.y += s
				r.width -= 2 * s
				r.height -= 2 * s
			}
		}
	}
}
