function makeHttpObject() {
	try {
		return new XMLHttpRequest()
	} catch (error) {
		console.error("XMLHttpRequest is not supported by this browser.", error)
	}
	try {
		return new ActiveXObject("Msxml2.XMLHTTP")
	} catch (error) {
		console.error("ActiveXObject 'Msxml2.XMLHTTP' is not supported by this browser.", error)
	}
	try {
		return new ActiveXObject("Microsoft.XMLHTTP")
	} catch (error) {
		console.error("ActiveXObject 'Microsoft.XMLHTTP' is not supported by this browser.", error)
	}

	throw new Error("Could not create HTTP request object.")
}

export function doHttpRequest(target, url, success, failure) {
	const request = makeHttpObject()
	if (request) {
		request.onreadystatechange = () => {
			if (request.readyState === 4) {
				if (request.status === 200 || request.status === 0) success(target, request.responseText)
				else if (failure) failure(request.status, request.statusText)
			}
		}
		request.open("GET", url, true)
		request.send(null)
	}
}
