import { Format } from "./core/elements/format"
import { Annotation } from "./tools/index"

export class CheckBox extends Annotation {
	constructor(chart, text, checked) {
		super(chart)

		this.transparent = true
		this.text = text
		this.checked = checked || true
		this.margins.left = 10

		this.cursor = "pointer"

		this.check = new Format(chart)
		this.check.fill = "white"

		this.chart.canvas.addEventListener("touchstart", () => {})
	}

	draw() {
		super.draw()

		const ctx = this.chart.ctx,
			x = this.position.x + 2

		const h = this.bounds.height * 0.6,
			y = this.position.y + (this.bounds.height - h) * 0.4

		this.check.rectangle(x, y, h, h)

		if (this.checked) {
			ctx.beginPath()
			ctx.moveTo(x + 3, y + 5)
			ctx.lineTo(x + 4, y + 8)
			ctx.lineTo(x + 7, y + 2)
			this.check.stroke.prepare()
			ctx.stroke()
		}
	}

	onclick(/*a,x,y*/) {
		this.checked = !this.checked
		if (this.onchange) this.onchange(this)
		return true
	}
}
