import { Format } from "../core/elements/format"
import { Series } from "../series"
import { Animation, Annotation } from "../tools/index"

/**
 * @constructor
 * @memberOf Tee
 * @class Parameters to draw a circular gauge meter.
 * @property {Number} [min=0] The minimum gauge range value.
 * @property {Number} [max=100] The maxnimum gauge range value.
 * @property {Number} [step=0] The increment between gauge range labels.
 * @property {Number} [value=0] The position of gauge hand inside the min max range.
 * @property {Number} [angle=280] Amount in degrees of the circular gauge size.
 * @property {Number} [rotation=0] Gauge rotation in degrees.
 * @property {Boolean} [rotateText=false] Gauge labels are rotated or not according to label angle position.
 * @property {String} [shape="circle"] Gauge style ("circle", "rectangle", "segment").
 * @property {Boolean} [drag.enabled=true] Allows mouse/touch dragging the Gauge hand to change current value.
 * @property {Format} bevel Formatting properties to outmost external gauge bevel.
 * @property {Format} center Formatting properties for center gauge symbol.
 */
export class CircularGauge extends Series {
	useAxes = false
	min = 0
	max = 100
	step = 0
	value = 0
	angle = 280
	rotation = 0
	rotateText = false
	shape = "circle"
	drag = { enabled: true }
	hands = []
	cx = 0
	cy = 0
	cex = 0
	cey = 0
	tick0 = 0
	tick1 = 0
	tickMin = 0
	tickText = 0
	initRot = 0
	endRot = 0
	_oldValue = 0
	_newValue = 0

	constructor(o, o2) {
		super(o, o2)

		this.bevel = new Format(this.chart)
		this.bevel.gradient.visible = true
		this.bevel.gradient.colors = ["white"]
		this.bevel.shadow.visible = false
		this.bevel.visible = false
		this.bevel.stroke.fill = ""

		this.center = new Format(this.chart)
		this.center.stroke.fill = ""
		this.center.gradient.visible = true
		this.center.size = 10
		this.center.visible = false
		this.center.shadow.visible = true
		this.center.gradient.offset = { x: 2, y: -2 }
		this.center.location = { x: 0, y: 0 } // %

		this.center.top = new Format(this.chart)
		this.center.top.size = 40 // %
		this.center.top.visible = true
		this.center.top.stroke.fill = ""
		this.center.top.gradient.colors = ["silver", "white"]
		this.center.top.gradient.visible = true
		this.center.top.gradient.direction = "topbottom"

		this.ticks = new Format(this.chart)
		this.ticks.length = 6 // %
		this.ticks.stroke.fill = "silver"
		this.ticks.visible = true
		this.ticks.outside = true
		this.ticks.triangle = false
		this.ticks.fill = "white"

		this.ticksBack = new Format(this.chart)
		this.ticksBack.stroke.fill = ""
		this.ticksBack.fill = "black"
		this.ticksBack.gradient.visible = true
		this.ticksBack.gradient.colors = ["red", "yellow", "green"]
		this.ticksBack.gradient.direction = "rightleft"
		this.ticksBack.visible = false
		this.ticksBack.radius = 0

		this.minor = new Format(this.chart)
		this.minor.stroke.fill = "silver"
		this.minor.visible = true
		this.minor.count = 4
		this.minor.shape = "" // ellipse

		this.minorBack = new Format(this.chart)
		this.minorBack.stroke.fill = ""
		this.minorBack.visible = false
		this.minorBack.fill = "white"
		this.minorBack.gradient.visible = false
		this.minorBack.gradient.direction = "leftright"
		this.minorBack.gradient.colors = ["green", "yellow", "red"]
		this.minorBack.radius = 0

		this.hand = this.addHand()

		this.back = new Format(this.chart)
		this.back.fill = "black"
		this.back.visible = true
		this.back.gradient.visible = true
		this.back.gradient.colors = ["rgba(255,126,95,0.8)", "rgba(254,180,123,0.8)"]
		this.back.stroke.fill = ""

		this.pointer = new Format(this.chart)
		this.pointer.size = 3
		this.pointer.fill = "black"
		this.pointer.stroke.fill = ""
		this.pointer.visible = false

		this.marks.location = { x: 0, y: 10 } // %
		this.marks.visible = true
		this.marks.format.fill = "black"
		this.marks.format.font.fill = "black"
		this.marks.format.gradient.visible = true
		this.marks.format.gradient.colors = ["rgba(255,126,95,0.6)", "rgba(254,180,123,0.6)"]
		this.marks.format.shadow.visible = true
		this.marks.format.shadow.blur = 8
		this.marks.format.shadow.color = "black"

		this.format.visible = true
		this.format.gradient.visible = true
		this.format.gradient.colors = ["white"]
		this.format.shadow.visible = true
		this.format.font.style = "12px Verdana"
		this.format.font.fill = "black"
		this.format.font.visible = true
		this.format.size = 2 // %
		this.format.round = { x: 6, y: 6 }

		this.format.padding = 0.5 // %

		this.units = new Annotation(this.chart)
		this.units.transparent = true
		this.units.format.font.fill = "black"
		this.units.location = { x: 0, y: 24 } // %

		this.bounds = this.getRect()

		this.hover.enabled = true

		this.animate = new Animation(this.chart, f => {
			this.value = this._oldValue + f * (this._newValue - this._oldValue)
			this.chart.draw()
		})

		this.animate.duration = 100
		this.animate.onstop = () => {
			this.value = this._newValue

			if (this.onchange) this.onchange(this)

			this.chart.draw()
		}
	}

	addHand() {
		const hand = new Format(this.chart)
		hand.size = 6
		hand.length = 60 // %
		hand.back = 20 // %
		hand.gradient.visible = true
		hand.gradient.colors[0] = "orange"
		hand.shadow.visible = true
		hand.shadow.blur = 12
		hand.shadow.color = "black"
		hand.stroke.fill = ""

		hand.pointer = true
		hand.shape = "needle" // "rectangle"

		hand.visible = true

		this.hands.push(hand)
		return hand
	}

	calcBounds() {
		return this.bounds.custom ? this.bounds : this.cellRect(this.bounds, true)
	}

	draw() {
		let ta = this.angle * 0.01745,
			r = this.calcBounds(),
			rax,
			ray
		const format = this.format
		const back = this.back
		const ticks = this.ticks
		const ticksBack = this.ticksBack
		const minor = this.minor
		const minorBack = this.minorBack
		const marks = this.marks
		const hand = this.hand
		const center = this.center
		const pointer = this.pointer

		this.cx = r.x + r.width * 0.5
		this.cy = r.y + r.height * 0.5

		if (this.bounds.custom) {
			rax = r.width
			ray = r.height
		} else {
			ray = rax = Math.min(r.width, r.height)
		}

		let tar = this,
			ctx = tar.chart.ctx,
			xx = 1.57,
			ra = rax

		this.initRot = tar.rotation * 0.01745 + (6.283 - ta) * 0.5
		while (this.initRot >= 6.283) this.initRot -= 6.283

		this.endRot = this.initRot + ta
		while (this.endRot >= 6.283) this.endRot -= 6.283

		function drawRange(t, p0, p1, start, end) {
			if (t.radius > 0) p1 = ra * t.radius * 0.01

			ctx.beginPath()
			ctx.arc(0, 0, p0, start, end, false)
			ctx.arc(0, 0, p1, end, start, true)

			t.draw(ctx, null, -p1, -p1, 2 * p1, 2 * p1)
		}

		function tryBack(t, p0, p1) {
			if (t.visible && t.fill !== "") {
				if (t.ranges && t.ranges.length > 0) {
					let sx = xx,
						endsx,
						old = t.fill,
						oldg = t.gradient.visible,
						tartot = tar.max - tar.min,
						difRot = tar.endRot - tar.initRot

					t.gradient.visible = false

					if (tar.inverted) sx += difRot

					for (let r = 0; r < t.ranges.length; r++) {
						const item = Math.min(tar.max, t.ranges[r].value)

						const rangev = r === 0 ? item : item - t.ranges[r - 1].value + tar.min

						if (tar.inverted) endsx = sx - (difRot * (rangev - tar.min)) / tartot
						else endsx = sx + (difRot * (rangev - tar.min)) / tartot

						t.fill = t.ranges[r].fill

						if (t.fill !== "") {
							if (tar.inverted) drawRange(t, p0, p1, endsx, sx)
							else drawRange(t, p0, p1, sx, endsx)
						}

						sx = endsx

						if (item >= tar.max) break
					}

					t.fill = old
					t.gradient.visible = oldg
				} else drawRange(t, p0, p1, xx, xx + (tar.endRot - tar.initRot))
			}
		}

		function drawShape(fo) {
			if (fo.visible)
				if (tar.shape === "circle") fo.ellipse(tar.cx, tar.cy, rax, ray)
				else if (tar.shape === "segment") {
					ctx.beginPath()

					const minAngle = tar.units.visible ? 275 : 240,
						rot0 = xx + tar.rotation * 0.01745 + (6.283 - Math.max(minAngle, tar.angle) * 0.01745) * 0.5

					const halfx = 0.5 * rax,
						halfy = 0.5 * ray

					ctx.arc(tar.cx, tar.cy, halfx, rot0, rot0 + Math.max(minAngle * 0.01745, ta), false)
					ctx.closePath()
					fo.draw(ctx, null, tar.cx - halfx, tar.cy - halfy, rax, ray)
				} else fo.rectangle(tar.cx - rax * 0.5, tar.cy - ray * 0.5, rax, ray)

			return fo.visible
		}

		if (drawShape(format)) {
			rax *= 1 - format.size * 0.01
			ray *= 1 - format.size * 0.01
			if (!this.bounds.custom) {
				ra = ray = rax
			}
		}

		if (drawShape(this.bevel)) {
			rax *= 1 - format.size * 0.002
			ray *= 1 - format.size * 0.002
			if (!this.bounds.custom) {
				ra = ray = rax
			}
		}

		drawShape(back)

		var o = ticks.outside,
			//a=this.mandatoryAxis,
			pos = this.min,
			range = this.max - this.min,
			step = this.step

		if (step === 0) step = range / 20

		step = Math.max(0.1, step)

		this.tick1 = o ? ra * 0.48 : ra * 0.41
		this.tick0 = this.tick1 - ra * (ticks.length * 0.01)
		this.tickText = o ? ra * 0.39 : this.rotateText ? ra * 0.46 : ra * 0.48
		this.tickMin = o ? ra * 0.45 : ra * 0.38

		format.font.prepare()

		function trunc(value) {
			return value | 0
		}

		var fh = format.textHeight("Wj"),
			tickCount = range / step,
			textStep = Math.max(1, trunc(tickCount / ((ra * ta) / 6.283 / fh)))

		ctx.fillStyle = format.font.fill

		ctx.save()

		var cex2 = this.cx,
			cey2 = this.cy

		if (tar.bounds.custom)
			if (rax > ray) cey2 += (0.75 * ray * ray) / rax
			else cex2 += (0.75 * rax * rax) / ray

		ctx.translate(cex2, cey2)

		ctx.rotate(this.initRot)

		tryBack(ticksBack, this.tick0, this.tick1)
		tryBack(minorBack, this.tickMin, this.tick1)

		function isHover(h, p, dif) {
			return h.enabled && h.valid ? (Math.abs(p - h.value) < dif ? h : null) : null
		}

		var roStep = (step * ta) / range / minor.count,
			totRot = this.initRot,
			offY = this.rotateText ? 0 : format.textHeight("Wj") * 0.3,
			tickIndex = 0

		if (!ticks.visible && o) this.tickText = this.tickMin * 0.9

		while (pos <= this.max) {
			if (ticks.visible) {
				const fTick = isHover(this.hover, pos, 0.2 * step) || ticks

				ctx.beginPath()
				ctx.moveTo(0, this.tick0)

				if (ticks.triangle) {
					ctx.lineTo(-3, this.tick1)
					ctx.lineTo(3, this.tick1)
					ctx.closePath()
					fTick.draw(ctx, -3, this.tick0, 3, this.tick1)
				} else {
					ctx.lineTo(0, this.tick1)

					fTick.stroke.prepare()
					ctx.stroke()
				}
			}

			if (format.font.visible && tickIndex % textStep === 0) {
				if (this.angle !== 360 || pos + step <= this.max) {
					const ts = this.tickText - format.textHeight() * format.padding

					ctx.translate(0, ts)

					const rr = this.rotateText ? Math.PI : totRot

					ctx.rotate(-rr)

					format.font.prepare()

					ctx.fillStyle = format.font.fill

					let ppos = tar.inverted ? this.max - pos + this.min : pos,
						st

					if (tar.ongetText) st = tar.ongetText(ppos)
					else if (trunc(ppos) === ppos) st = ppos.toFixed(0)
					else st = ppos.toFixed(this.decimals)

					ctx.fillText(st, 0, offY)

					ctx.rotate(rr)
					ctx.translate(0, -ts)
				}
			}

			if (minor.visible) {
				if (pos < this.max)
					for (let mit = 0; mit < minor.count; mit++) {
						ctx.rotate(roStep)

						if (mit < minor.count - 1) {
							const miStep = step / minor.count,
								nPos = pos + (mit + 1) * miStep,
								fminTick = isHover(this.hover, nPos, 0.2 * miStep) || minor

							if (nPos > this.max) break

							if (minor.shape === "ellipse") minor.ellipse(0, (this.tickMin + this.tick1) * 0.5, minor.size, minor.size)
							else {
								ctx.beginPath()
								ctx.moveTo(0, this.tickMin)
								ctx.lineTo(0, this.tick1)

								fminTick.stroke.prepare()
								ctx.stroke()
							}
						}
					}
			} else ctx.rotate(roStep * minor.count)

			totRot += roStep * minor.count

			pos += step
			tickIndex++
		}

		ctx.restore()

		// marker
		//var m=this.marks;
		if (marks.visible) {
			marks.text = this.value.toFixed(this.decimals)
			marks.resize()
			marks.position.x = this.cx - marks.bounds.width * 0.5 + marks.location.x * rax * 0.01
			marks.position.y = this.cy + marks.location.y * ray * 0.01
			marks.draw()
		}

		// units;
		const u = this.units
		if (u.visible) {
			u.resize()
			u.position.x = this.cx - u.bounds.width * 0.5 + u.location.x * rax * 0.01
			u.position.y = this.cy + u.location.y * ray * 0.01
			u.draw(ctx)
		}

		ctx.save()

		// hands
		hand.value = this.value

		for (let h = 0; h < this.hands.length; h++)
			if (this.hands[h].visible) this.drawHand(this.hands[h], ta, range, rax, ray, ra, center, ctx, pointer)

		ctx.restore()

		// Center:
		if (center.visible) {
			const ces = ra * center.size * 0.01

			center.ellipse(this.cex, this.cey, ces, ces)

			if (center.top.visible) {
				const cet = ces * center.top.size * 0.01
				center.top.ellipse(this.cex, this.cey, cet, cet)
			}
		}
	}

	drawHand(han, ta, range, rax, ray, ra, ce, ctx, po) {
		han.value = this.limitValue(han.value)

		var ppos = this.inverted ? this.max - han.value + this.min : han.value,
			handRot = this.rotation * 0.01745 + (9.4248 - ta) * 0.5 + (ta * (ppos - this.min)) / range

		this.cex = this.cx + rax * ce.location.x * 0.005
		this.cey = this.cy + ray * ce.location.y * 0.005

		ctx.save()

		ctx.translate(this.cex, this.cey)
		ctx.rotate(handRot)

		var hs = han.size,
			rah = ra * han.back * 0.5 * 0.01,
			rad = Math.min(hs, 6),
			raend = ra * han.length * 0.5 * 0.01

		ctx.beginPath()

		if (hs > 1) {
			ctx.moveTo(-rah + rad, -hs)

			if (han.shape === "needle") {
				ctx.quadraticCurveTo(-rah, -hs, -rah, -hs + rad)
				ctx.lineTo(-rah, hs - rad)
				ctx.quadraticCurveTo(-rah, hs, -rah + rad, hs)
				ctx.lineTo(raend, 0)
			} else {
				ctx.lineTo(-rah + rad, hs)
				ctx.lineTo(raend, hs)
				ctx.lineTo(raend, -hs)
			}

			ctx.closePath()
		} else {
			ctx.moveTo(-rah, 0)
			ctx.lineTo(raend, 0)
		}

		if (hs > 1) han.draw(ctx, null, -rah, -hs, rah + raend, 2 * hs)
		else {
			han.stroke.prepare()
			ctx.strokeStyle = han.fill
			ctx.stroke()
		}

		if (this.ondrawHand) this.ondrawHand(this, han)

		// Pointer:
		if (han.pointer && po.visible) po.ellipse((this.tickMin + this.tick1) * 0.5, 0, po.size, po.size)

		ctx.restore()
	}

	limitValue(v) {
		return Math.min(this.max, Math.max(this.min, v))
	}

	setValue(v) {
		v = this.limitValue(v)

		const res = this.value !== v

		if (res) {
			if (this.animate.active && this.animate.duration > 0) {
				this._oldValue = this.value
				this._newValue = v
				this.animate.animate(this.chart)
			} else {
				this.value = v

				if (this.onchange) this.onchange(this)
			}
		}

		return res
	}

	onclick() {}

	clicked() {
		this.dragging = false
		return -1
	}

	inValue(p, r) {
		if (!r.contains(p)) return false

		var dx = p.x - this.cex,
			dy = p.y - this.cey,
			d = Math.sqrt(dx * dx + dy * dy)

		var ang = Math.atan2(dy, dx) - Math.PI * 0.5
		while (ang < 0) ang += 6.283

		var rIni, rEnd, val

		if (this.initRot > this.endRot) {
			rIni = this.endRot
			rEnd = this.initRot
			val = ang >= rEnd || ang <= rIni
		} else {
			rEnd = this.endRot
			rIni = this.initRot
			val = ang >= rIni && ang <= rEnd
		}

		if (val) {
			let res

			if (this.initRot > this.endRot)
				if (ang > rEnd) res = (ang - rEnd) / (6.283 - rEnd + rIni)
				else res = (6.283 - rEnd + ang) / (6.283 - rEnd + rIni)
			else res = (ang - rIni) / (rEnd - rIni)

			let v = this.min + (this.max - this.min) * res

			if (this.inverted) v = this.min + (this.max - this.min) * (1 - res)

			p.value = v

			p.inTicks = d >= Math.min(this.tick0, this.tickText) && d <= this.tick1

			return true
		} else {
			p.inTicks = false
			return false
		}
	}

	mousemove(p) {
		function changeHover(g, v) {
			if (g.hover.value !== v) {
				g.hover.value = v
				g.hover.valid = v !== null
				requestAnimationFrame(() => {
					g.chart.draw()
				})
			}
		}

		const r = this.calcBounds(),
			ok = this.inValue(p, r)
		if (
			this.dragging ||
			(/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) && this.drag.enabled)
		) {
			if (ok && this.setValue(p.value)) {
				this.chart.draw()
			}

			this.chart.newCursor = "pointer"
		} else if (p.inTicks && this.drag.enabled) {
			changeHover(this, p.value)
			this.chart.newCursor = "pointer"
		} else {
			changeHover(this, null)
		}
	}

	mousedown(e) {
		const p = { x: 0, y: 0 }

		if (this.drag.enabled) {
			const r = this.calcBounds()
			this.chart.calcMouse(e, p)

			if (this.inValue(p, r)) {
				this.dragging = true

				this.hover.value = null
				this.hover.valid = false

				if (this.setValue(p.value)) this.chart.draw()
			} else this.dragging = false

			return this.dragging
		} else return false
	}

	/**
	 * @private
	 */
	setChart(series, chart) {
		super.setChart(series, chart)
		series.back.setChart(chart)
		series.center.setChart(chart)
		series.center.top.setChart(chart)
		series.ticks.setChart(chart)
		series.ticksBack.setChart(chart)
		series.minor.setChart(chart)
		series.minorBack.setChart(chart)
		series.hand.setChart(chart)
		series.units.setChart(chart)
		series.pointer.setChart(chart)
		series.bevel.setChart(chart)
	}
}
