function drawSpline(ctx, pts, t, move, closed) {
	let cp = []
	const n = pts.length

	function point(x0, y0, x1, y1, x2, y2, tension) {
		function square(x) {
			return x * x
		}

		const d = Math.sqrt(square(x1 - x0) + square(y1 - y0))
		const a = (tension * d) / (d + Math.sqrt(square(x2 - x1) + square(y2 - y1)))
		const b = tension - a

		return [x1 + a * (x0 - x2), y1 + a * (y0 - y2), x1 - b * (x0 - x2), y1 - b * (y0 - y2)]
	}

	if (closed) {
		if (move) {
			ctx.moveTo(pts[0], pts[1])
		}

		pts.push(pts[0], pts[1], pts[2], pts[3])
		pts.unshift(pts[n - 1])
		pts.unshift(pts[n - 1])

		for (let i = 0; i < n; i += 2) {
			cp = cp.concat(point(pts[i], pts[i + 1], pts[i + 2], pts[i + 3], pts[i + 4], pts[i + 5], t))
		}

		cp = cp.concat(cp[0], cp[1])

		for (let i = 2; i < n + 2; i += 2) {
			ctx.bezierCurveTo(cp[2 * i - 2], cp[2 * i - 1], cp[2 * i], cp[2 * i + 1], pts[i + 2], pts[i + 3])
		}
	} else {
		for (let i = 0; i < n - 4; i += 2) {
			cp = cp.concat(point(pts[i], pts[i + 1], pts[i + 2], pts[i + 3], pts[i + 4], pts[i + 5], t))
		}

		if (move) {
			ctx.moveTo(pts[0], pts[1])
		}

		ctx.quadraticCurveTo(cp[0], cp[1], pts[2], pts[3])

		for (let i = 2; i < n - 5; i += 2) {
			ctx.bezierCurveTo(cp[2 * i - 2], cp[2 * i - 1], cp[2 * i], cp[2 * i + 1], pts[i + 2], pts[i + 3])
		}

		ctx.quadraticCurveTo(cp[2 * n - 10], cp[2 * n - 9], pts[n - 2], pts[n - 1])
	}
}

class Scroller extends Chart {
	constructor(canvas, target) {
		super(canvas)

		this.target = target

		this.aspect.clip = false
		this.panel.transparent = true
		this.title.visible = false

		this.scroller = new Slider(this)
		const scroller = this.scroller
		scroller.useRange = true
		scroller.thumbSize = 100

		const u = scroller.thumb
		u.shadow.height = 0
		u.transparency = 0.6
		u.stroke.fill = "black"
		u.shadow.visible = false

		scroller.horizontal = true
		const b = scroller.bounds
		b.x = 0
		b.y = 0
		b.width = this.bounds.width
		b.height = this.bounds.height
		scroller.margin = 0

		scroller.lock = false

		this.tools.add(scroller)

		const owner = this

		target.ondraw = () => {
			if (!scroller.lock) owner.draw()
		}
		target.onscroll = function () {
			const a = this.axes.bottom
			const li = this.series
			const mi = li.minXValue()
			const ma = li.maxXValue()
			const dif = a.maximum - a.minimum

			if (a.minimum < mi) {
				a.minimum = mi
				a.maximum = a.minimum + dif
			}
			if (a.maximum > ma) {
				a.maximum = ma
				a.minimum = a.maximum - dif
			}
		}

		scroller.onChanging = function (s, v) {
			const width = s.bounds.width || 1
			const range = s.max - s.min
			let r = ((s.thumbSize * range) / width) * 0.5
			const li = target.series
			const mi = li.minXValue()
			const ma = li.maxXValue()

			if (!Number.isFinite(r)) r = 0

			if (v - r < mi) v = mi + r
			else if (v + r > ma) v = ma - r

			target.axes.bottom.setMinMax(v - r, v + r)
			this.lock = true

			//requestAnimationFrame(function() {target.draw();});

			target.draw()
			this.lock = false

			if (owner.onChanging) owner.onChanging(owner, v - r, v + r)

			return v
		}

		scroller.onDrawThumb = s => {
			const r = target.chartRect
			const ctx = target.ctx
			const cRect = new Rectangle(scroller.bounds.x, scroller.bounds.y, scroller.bounds.width, scroller.bounds.height)
			target.chartRect = cRect
			target.ctx = scroller.chart.ctx

			function saveAxis(axis, data) {
				const res = {
					mi: axis.minimum,
					ma: axis.maximum,
					sp: axis.startPos,
					ep: axis.endPos
				}
				restoreAxis(axis, data)
				return res
			}

			function restoreAxis(axis, old) {
				axis.minimum = old.mi
				axis.maximum = old.ma
				axis.startPos = old.sp
				axis.endPos = old.ep
				axis.scale = (old.ep - old.sp) / (old.ma - old.mi)
			}

			const b = scroller.bounds
			const c = target
			const li = c.series

			s.min = li.minXValue()
			s.max = li.maxXValue()

			const h = saveAxis(c.axes.bottom, {
				sp: b.x,
				ep: b.x + b.width,
				mi: s.min,
				ma: s.max
			})
			const v = saveAxis(c.axes.left, {
				sp: b.y,
				ep: b.y + b.height,
				mi: li.minYValue(),
				ma: li.maxYValue()
			})

			const p = (h.mi + h.ma) * 0.5
			const dif = h.ma - h.mi
			const totalRange = s.max - s.min

			//if (s.position!=p) {
			s.thumbSize = totalRange !== 0 ? (dif * s.bounds.width) / totalRange : s.bounds.width
			const ra = dif * 0.5
			if (owner.onChanging) owner.onChanging(owner, p - ra, p + ra)
			s.position = p
			//}

			c.series.each(seriesItem => {
				if (seriesItem.visible && seriesItem.useAxes) {
					if (seriesItem.pointer !== undefined) {
						//disable points in Scroller. Bug sizing
						const oldVisible = seriesItem.pointer.visible
						seriesItem.pointer.visible = false
						seriesItem.draw()
						seriesItem.pointer.visible = oldVisible
					} else seriesItem.draw()
				}
			})

			restoreAxis(c.axes.bottom, h)
			restoreAxis(c.axes.left, v)

			c.chartRect = r
			c.ctx = ctx
		}
	}

	useRange(value) {
		this.scroller.useRange = value
		this.draw()
	}

	invertThumb(value) {
		this.scroller.invertThumb = value
		this.draw()
	}

	setBounds(x, y, width, height) {
		this.bounds.x = x
		this.bounds.y = y
		this.bounds.width = width
		this.bounds.height = height

		const b = this.scroller.bounds
		b.x = x
		b.y = y
		b.width = width
		b.height = height
	}
}

function SliderControl(canvas) {
	const tmpChart = new Chart(canvas)
	tmpChart.panel.transparent = true
	tmpChart.title.visible = false

	const slider = new Slider(tmpChart)

	slider.bounds.x = slider.thumbSize + 1
	slider.bounds.width = tmpChart.canvas.width - 2 * slider.thumbSize - 2
	slider.bounds.y = (tmpChart.canvas.height - slider.bounds.height) * 0.5

	tmpChart.tools.add(slider)
	return slider
}

export { drawSpline, Scroller, SliderControl }
