import { SVGMap } from "./svg-map"

// !MIGRATION - In v5 remove the legacy `call` method and the `copyOwnProperties` helper, and update all usages to use `new LayoutMap(...)` instead of `LayoutMap.call(...)`.

/**
 * Copies own properties from an initialized instance to an existing object.
 * This keeps legacy `Tee.LayoutMap.call(this, ...)` flows working.
 */
function copyOwnProperties(target, source) {
  for (const key of Reflect.ownKeys(source)) {
    const descriptor = Object.getOwnPropertyDescriptor(source, key)
    if (descriptor) {
      Object.defineProperty(target, key, descriptor)
    }
  }
}

/**
 * @constructor
 * @augments SVGMap
 * @class SVG LayoutMap.
 */
class LayoutMap extends SVGMap {
  constructor(id, left, top, width, height) {
    const bounds = {
      x: left || 0,
      y: top || 0,
      width: width || 10,
      height: height || 10,
    }

    super(id, 0, 0, bounds.width, bounds.height)

    this.bounds = bounds
    this.size.offx = 0
    this.size.offy = 0
    this.pointsAttribute = "points"
    this.labels = { AF: "PN" }

    this.svg.appendChild(this.content)
  }

  /**
   * Legacy compatibility shim.
   * Allows `Tee.LayoutMap.call(thisArg, ...)` while keeping the implementation as a class.
   */
  static call(thisArg, ...args) {
    if (thisArg == null) {
      throw new TypeError("LayoutMap.call target must be an object")
    }

    const instance = new this(...args)
    copyOwnProperties(thisArg, instance)
    return thisArg
  }

  /**
   * Draws a path
   */
  static nPPath(t, instruct, clr, wdth, ps) {
    // if ((!this.filter) || (this.filter.indexOf(t) != -1)) {
    const path = document.createElementNS(this.ns, "path")
    path.setAttribute("d", instruct)
    path.setAttribute(this.pointsAttribute, ps)
    path.style.stroke = clr
    path.style.strokeWidth = wdth
    this.content.appendChild(path)
    // }
  }

  /*newpath = document.createElementNS("SVG","path");
newpath.setAttribute("id", "pathIdD");
newpath.setAttribute("d", "M 1,97.857143 C 19.285714,96.428571 24.016862,131.64801 90.714286,132.85714 140.78762,133.7649 202.79376,66.16041 202.79376,66.16041");
newpath.setAttribute("stroke", "black");
newpath.setAttribute("stroke-width", 3);
newpath.setAttribute("opacity", 1);
newpath.setAttribute("fill", "none");

document.getElementById("fullPageID").appendChild(newpath);*/

  /**
   * Draws a polygon
   * @param {string} t element id.
   * @param {point[]} ps Polygon points.
   */
  static nP(t, ps) {
    if ((!this.filter) || (this.filter.indexOf(t) != -1)) {
      const polygon = document.createElementNS(this.ns, "polygon")
      polygon.setAttribute("id", t)
      polygon.setAttribute(this.pointsAttribute, ps)
      this.content.appendChild(polygon)
    }
  }

  /**
   * Draws a circle/ellipse
   * @param {string} t element id.
   * @param {number} aX Centre x location.
   * @param {number} aY Centre y location.
   * @param {number} aRX x radius.
   * @param {number} aRX y radius.
   */
  static nC(t, aX, aY, aRX, aRY) {
    // circle/ellipse
    const shape = document.createElementNS(this.ns, "ellipse")
    shape.setAttribute("cx", aX)
    shape.setAttribute("cy", aY)
    shape.setAttribute("rx", aRX)
    shape.setAttribute("ry", aRY)
    shape.setAttribute("id", t)
    //shape.setAttributeNS(null, "fill", aColor);

    this.content.appendChild(shape)
  }

  /**
   * Draws a polygon
   * @param {string} t element id.
   * @param {Color} clr Stroke color.
   * @param {number} wdth Stroke width.
   * @param {point[]} ps Polygon points.
   */
  static nPEnh(t, clr, wdth, ps) {
    if ((!this.filter) || (this.filter.indexOf(t) != -1)) {
      const polygon = document.createElementNS(this.ns, "polygon")
      polygon.setAttribute("id", t)
      polygon.setAttribute(this.pointsAttribute, ps)
      polygon.style.stroke = clr
      polygon.style.strokeWidth = wdth
      this.content.appendChild(polygon)
    }
  }

  /*
  function nP(t, ps) {
    if ((!_this.filter) || (_this.filter.indexOf(t)!=-1)) {
      p=d.createElementNS(ns, "polygon");
      p.setAttribute("id", t);
      p.setAttribute(po,ps);
      content.appendChild(p);
    }
  }
*/

  /**
   * Draws a text element
   * @param {string} t element id.
   * @param {number} aX Text x location.
   * @param {number} aY Text y location.
   * @param {string} aFamily Font family.
   * @param {string} text Text to render.
   */
  static nPTxt(t, aX, aY, aFamily, text) {
    if ((!this.filter) || (this.filter.indexOf(t) != -1)) {
      const txt = document.createElementNS(this.ns, "text")
      //txt.setAttribute("id", t);
      txt.setAttribute("textContent", text)
      txt.setAttribute("x", aX)
      txt.setAttribute("y", aY)
      //txt.setAttribute("fill", "blue");
      txt.setAttribute("font-family", aFamily)

      this.content.appendChild(txt)
    }
  }
}

export { LayoutMap }
