import { Animation } from "./tools/index"
import { trunc } from "./utils"

/**
 * @constructor
 * @extends Animation
 * @class Animates Series marks items.
 */
export class MarksAnimation extends Animation {
	constructor(target) {
		super(target)

		if (target && target instanceof Tee.Series) {
			this.series = target
			this.chart = target.chart
		} else {
			this.series = null
		}

		this.current = -1
		this.marks = this.series?.marks
		this.oldGetText = null
	}

	marksText(_series, index, result) {
		if (index <= this.current) {
			return result
		}

		return ""
	}

	start() {
		if (!this.marks) {
			return
		}

		this.oldGetText = this.marks.ongettext
		this.marks.ongettext = this.marksText.bind(this)
	}

	stop() {
		if (this.marks) {
			this.marks.ongettext = this.oldGetText
		}

		this.current = -1
	}

	doStep(f) {
		if (!this.series) {
			return
		}

		this.current = trunc(this.series.data.values.length * f)
	}
}
